                "s.t:49|s.e:g.f|p.c:#fffcc563", "s.t:49|s.e:g.s|p.c:#ffd69a3a",
                "s.t:50|s.e:g.f|p.c:#fffff4a4", "s.t:50|s.e:g.s|p.c:#ffd8c874",
                "s.t:51|s.e:g.f|p.c:#ffffffff", "s.t:51|s.e:g.s|p.c:#ffc9c9c9", "s.e:l.t.f|p.c:#ff222222", "s.e:l.t.s|p.c:#ffffffff"
