            "s.t:49|s.e:g.f|p.c:#fffdd35c", "s.t:49|s.e:g.s|p.c:#ffb5842b",
            "s.t:50|s.e:g.f|p.c:#ffffffa1", "s.t:50|s.e:g.s|p.c:#ffc0b16f",
            "s.t:51|s.e:g.f|p.c:#ffffffff", "s.t:51|s.e:g.s|p.c:#ffbfbfbf", "s.e:l.t.f|p.c:#ff222222", "s.e:l.t.s|p.c:#ffffffff"
