        if (!id.name && !id.email && !ugfMapsIdentity().signedIn) {
            return '<a class="signin" href="https://accounts.google.com/ServiceLogin?continue=' +
                encodeURIComponent(window.location.href) + '">Sign in</a>';
        }
        return '<div id="ugf-maps-account">' +
            '<a class="plusname" href="' + esc(gPlusLink || "https://plus.google.com/") + '">' +
            (ugfGmailNameMode() === "name" ? "+" + esc(ugfGmailPlusName()) : esc(ugfGmailDisplayName())) + "</a>" +
            (withApps ? '<a class="ic grid" href="https://www.google.com/intl/en/about/products/" title="Apps">' + ugfGmailIcon("apps", 20) + "</a>" : "") +
            '<span class="nbox">0</span>' +
            '<span class="sharebtn"><b>+</b> Share</span>' +
            '<span class="pfpwrap">' + ugfGmailAvatar() + '<i class="car">&#9662;</i></span></div>';
