            const z = add("zoom15", '<img src="' + K.zoom + '" alt=""><a class="zi" title="Zoom in"></a><a class="zo" title="Zoom out"></a>');
            z.querySelector(".zi").onclick = map.zoomIn;
            z.querySelector(".zo").onclick = map.zoomOut;
