            '.foot.m2014 .copy.r, .foot.m2015 .copy.r, .foot.m2019 .copy.r, .foot.m2022 .copy.r { position: static; display: flex; align-items: center; gap: 14px; background: rgba(255,255,255,.7); padding: 0 6px 0 4px; height: 13px; font: 10px Roboto, arial, sans-serif; color: #444; }',
            '.foot.m2014 .copy.r a, .foot.m2015 .copy.r a, .foot.m2019 .copy.r a, .foot.m2022 .copy.r a { color: #444 !important; text-decoration: none; }',
            '.foot.m2014 .scale, .foot.m2015 .scale, .foot.m2019 .scale, .foot.m2022 .scale { position: static; display: flex; align-items: center; gap: 4px; }',
            '.foot.m2014 .scale i, .foot.m2015 .scale i, .foot.m2019 .scale i, .foot.m2022 .scale i { height: 3px; border-width: 1px; border-color: #444; margin: 2px 0 0 0; }',
            '.foot.m2014 .scale .sl, .foot.m2015 .scale .sl, .foot.m2019 .scale .sl, .foot.m2022 .scale .sl { font-size: 10px; }',
            '.foot .glogo.mid { position: fixed; left: 50%; bottom: 14px; margin-left: -31px; }',
            '.foot .glogo.mid[width="70"] { margin-left: -35px; bottom: 12px; }',
