    function ugfEscapeHtml(t) {
        return String(t == null ? "" : t)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;");
    }
    function ugfParseResultsFrom(doc) {
        const out = [];
        const heads = doc.querySelectorAll("h3");
        heads.forEach(function(h) {
            const a = h.closest("a[href]");
            if (!a) {
                return;
            }
            let href = a.getAttribute("href") || "";
            if (href.indexOf("/url?") === 0) {
                try {
                    href = new URLSearchParams(href.split("?")[1]).get("q") || href;
                } catch (e) {}
            }
            if (href.indexOf("http") !== 0) {
                return;
            }
            if (href.indexOf("google.com/search") > -1) {
                return;
            }
            const title = (h.textContent || "").trim();
            if (!title) {
                return;
            }
            let desc = "";
            let block = a.closest("div[data-hveid]") || a.parentElement;
            for (let hop = 0; hop < 4 && block; hop++) {
                const spans = block.querySelectorAll("div > span, div[data-sncf] span");
                for (let i = 0; i < spans.length; i++) {
                    const t = (spans[i].textContent || "").trim();
                    if (t.length > 40 && t.indexOf(title) === -1) {
                        desc = t;
                        break;
                    }
                }
                if (desc) {
                    break;
                }
                block = block.parentElement;
            }
            out.push({ title: title, href: href, desc: desc });
        });
        return out;
    }
    // 1997-1998: the "N results" dropdown limits how many result pages the Goooogle pager offers
    // (10 results = page 1 only, 30 = pages 1-3, 100 = pages 1-10).
    function ugfEraPageLimit() {
        const era = ugfRetroEra();
        if (era !== "gplex1997" && era !== "gplex1998") {
            return;
        }
        let num = 10;
        let start = 0;
        try {
            const sp = new URLSearchParams(window.location.search);
            num = parseInt(sp.get("num") || "", 10) || parseInt(localStorage.getItem("UGF_ERA_NUM") || "10", 10) || 10;
            start = parseInt(sp.get("start") || "0", 10) || 0;
        } catch (e) {}
        const maxPages = Math.max(1, Math.min(10, Math.round(num / 10)));
        const curPage = Math.floor(start / 10) + 1;
        const h = document.querySelector("html");
        h.setAttribute("era-max-pages", String(maxPages));
        if (curPage >= maxPages) {
            h.setAttribute("era-last-page", "");
        }
    }
    // ---- Reverse image search (Google Lens) themed as "Search by image" (2011-2016) / "Google Lens" (2017+) ----
    // Google's Lens page stays visible until enough visual matches are found; if parsing fails it is left untouched.
    // ---- "Search by image" (2011-2016) and "Google Lens" (2017+) entry: camera icon + panel, no Google page needed ----
    const UGF_CAMERA_SVG = '<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path fill="currentColor" d="M9 3 7.2 5H4a2 2 0 0 0-2 2v11a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-3.2L15 3H9zm3 5a4.5 4.5 0 1 1 0 9 4.5 4.5 0 0 1 0-9zm0 2a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5z"/></svg>';
    function ugfSbiSearchUrl(u) {
        u = (u || "").trim();
        if (!/^https?:\/\//i.test(u)) {
            return false;
        }
        window.location = "https://lens.google.com/uploadbyurl?url=" + encodeURIComponent(u);
        return true;
    }
    function ugfSbiUploadForm() {
        const form = document.createElement("form");
        form.method = "POST";
        form.enctype = "multipart/form-data";
        form.style.display = "none";
        const file = document.createElement("input");
        file.type = "file";
        file.name = "encoded_image";
        file.accept = "image/*";
        form.appendChild(file);
        const send = function() {
            if (!file.files || !file.files.length) {
                return;
            }
            form.action = "https://lens.google.com/v3/upload?hl=" + encodeURIComponent(UGF_LANG_HL) + "&re=df&ep=gsbubb&st=" + Date.now();
            form.submit();
        };
        file.addEventListener("change", send);
        return { form: form, file: file, send: send };
    }
    function ugfSbiHandleDrop(ev, up) {
        ev.preventDefault();
        const dt = ev.dataTransfer;
        if (!dt) {
            return;
        }
        if (dt.files && dt.files.length) {
            try {
                up.file.files = dt.files;
                up.send();
                return;
            } catch (e) {}
        }
        const uri = (dt.getData("text/uri-list") || dt.getData("text/plain") || "").split("\n")[0];
        ugfSbiSearchUrl(uri);
    }
